/*---
description: NFKC agrees with Node for every code point U+0C0000 through U+0CFFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3917191621, 3263140293, 2591556037, 3662053829, 3522896325, 2736601541, 133452229, 3764025797, 1413349829, 643543493, 2987352517, 47194565, 3397810629, 2502410693, 2122809797, 3878064581];
const blocks = ["NFKC U+0C0000-U+0C0FFF", "NFKC U+0C1000-U+0C1FFF", "NFKC U+0C2000-U+0C2FFF", "NFKC U+0C3000-U+0C3FFF", "NFKC U+0C4000-U+0C4FFF", "NFKC U+0C5000-U+0C5FFF", "NFKC U+0C6000-U+0C6FFF", "NFKC U+0C7000-U+0C7FFF", "NFKC U+0C8000-U+0C8FFF", "NFKC U+0C9000-U+0C9FFF", "NFKC U+0CA000-U+0CAFFF", "NFKC U+0CB000-U+0CBFFF", "NFKC U+0CC000-U+0CCFFF", "NFKC U+0CD000-U+0CDFFF", "NFKC U+0CE000-U+0CEFFF", "NFKC U+0CF000-U+0CFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 786432 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
